good.code:
// First index i with a[i] >= x, or a.length if none.
function lowerBound(a, x) {
  let lo = 0, hi = a.length // answer is in [lo, hi]
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2)
    if (a[mid] < x) lo = mid + 1
    else hi = mid
  }
  return lo
}
// [] -> 0, [1] x=0 -> 0, [1] x=2 -> 1, [1,2,2,2,3] x=2 -> 1

